-- To do fff39d25 (Salling "Den du ved nok kage"): statuskommentar med tjekliste til emballagen.
insert into public.admin_todo_comments (todo_id, body)
select t.id, 'Status 13. okt. 2026: Databasen er kontrolleret mod Open Food Facts og en websøgning. EAN 5712877889767 er gyldig (kontrolciffer passer), navn, mærke (Salling) og kategori (Kageblandinger) hænger sammen, kilde Bilka, ikke verificeret. Open Food Facts kender ikke stregkoden, og der findes ingen andre offentlige kilder. Ingredienslisten (flormelis, kokosmel, fedtreduceret kakaopulver, skummetmælkspulver + spor) ligner kun en glasur-/delliste, ikke hele kagen, og næringsindholdet mangler kulhydrater. Appen viser rigtigt "Kan ikke vurderes". Det afgøres kun på emballagen. Tjekliste: 1) Står stregkode og navn som i appen? 2) Er det en kageblanding (æg, smør, mælk tilsættes selv) eller kun en glasurblanding? 3) Skriv hele ingredienslisten af, inkl. flere afsnit som "Kage:" og "Glasur:". 4) Hvilke "Kan indeholde spor af" står der? Samme tjek gælder Dannevirke "Krydderkage", Valsemøllen "Krydderkage m. Frosting" og Salling/Valsemøllen "Drømmekage". To do''en står åben til emballagen er tjekket.'
  from public.admin_todos t
 where t.id = 'fff39d25-13a3-4313-b228-6460316488aa' and t.status <> 'done'
   and not exists (select 1 from public.admin_todo_comments c where c.todo_id = t.id and c.body like 'Status 13. okt. 2026: Databasen er kontrolleret%');
